    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormControlEventHandler(formControlStr(CustOpenTransReverse, ReverseNew), FormControlEventType::Clicked)]
    public static void ReverseNew_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        CustTrans           custTrans;
        FormRun             formRun = sender.formRun() as FormRun;
        CustTable           custTable;

        custTrans = sender.formRun().dataSource(1).cursor();

        custTable = CustTable::find(custTrans.AccountNum);

        if(custTable.CredManAccountStatusId == "@MET:Csd")
        {
            throw error("@MET:ClosedAccountsSettle");
        }

    }
